pub(crate) fn no_row_attributes(an: &mut crate::port::Cells, id: i32, withasc: i32) -> i32 {
    // An answer whose engine gives no row attributes: one line, its baseline level at y = 100 px, and the words `none` (x-height
    // letters, tops at 80), with `withasc` 1 `bldh` (tops at 66: 34 px above the baseline) and `gyp` (bottoms at 106).
    let at: i32 = an_ocr(an, id);
    let w0: i32 = an_ocr_word(an, at, 10, 80, 70, 20, 900, 0, 0);
    an_ocr_cp(an, w0, 110);
    if withasc == 1 {
        let w1: i32 = an_ocr_word(an, at, 90, 66, 70, 34, 900, 0, 0);
        an_ocr_cp(an, w1, 98);
        let w2: i32 = an_ocr_word(an, at, 170, 80, 50, 26, 900, 0, 0);
        an_ocr_cp(an, w2, 103);
    }
    ox_begin(an, 0, 0, 0, 0, -1, 0, -1, -1, 1, 1, 0, 0, 0);
    ox_line(an, 10, 66, 210, 46, 10, 100, 220, 100, 0, 0, 0, -1, -1, -1);
    ox_block(an, 10, 66, 210, 46, 0, 0, 0);
    let x0: i32 = ox_word(an, 0, 0, -1, 0);
    sym1(an, x0, 10, 80, 20, 110);
    sym1(an, x0, 25, 80, 20, 111);
    sym1(an, x0, 40, 80, 20, 110);
    sym1(an, x0, 55, 80, 20, 101);
    if withasc == 1 {
        let x1: i32 = ox_word(an, 0, 0, -1, 0);
        sym1(an, x1, 90, 66, 34, 98);
        sym1(an, x1, 105, 66, 34, 108);
        sym1(an, x1, 120, 66, 34, 100);
        sym1(an, x1, 135, 66, 34, 104);
        let x2: i32 = ox_word(an, 0, 0, -1, 0);
        sym1(an, x2, 170, 80, 26, 103);
        sym1(an, x2, 185, 80, 26, 121);
        sym1(an, x2, 200, 80, 26, 112);
    }
    an_ocr_end(an, at);
    return at;
}
#[test]
fn test_a_line_is_measured_from_its_symbols_when_the_engine_gives_no_row_attributes() {
    let an: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let oruns: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let olines: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let owords: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let osyms: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let at: i32 = no_row_attributes(an, 2, 1);
    sc_page(an, at, 1, 2, 1, 17712, 22848, 738, 952, 30000, 0, 0, 0, 0, 0, 17712, 22848, 6579573, &mut crate::port::Cells::new(), &mut crate::port::Cells::new(), et, &mut crate::port::Cells::new(), &mut crate::port::Cells::new(), oruns, &mut crate::port::Cells::new(), olines, owords, osyms, &mut crate::port::Cells::new(), wd, ln, &mut crate::port::Cells::new());
    crate::testport::assert_eq(ol_get(olines, 0, olf_xheight()), -1, "the evidence keeps what the engine said: nothing");
    crate::testport::assert_eq(wd_count(wd), 3, "three words");
    crate::testport::assert_eq(wd_get(wd, 0, wf_size()), 1117, "the tall letters reach 34 px: 816 cpt, over 0.73");
    crate::testport::assert_eq(ln_get(ln, 0, lh_y0()), 2400 - 816, "the box's top is the baseline less the ascender line");
    crate::testport::assert_eq(ln_get(ln, 0, lh_y1()), 2400 + 144, "and its bottom the baseline plus the median depth of g, y, p: 6 px");
}
