    crate::testport::assert_eq(ln_get(ln, 0, lh_y0()), 2400 - 720, "the box's top");
    crate::testport::assert_eq(ln_get(ln, 0, lh_y1()), 2400 + 194, "and its bottom: 0.27 of the ascender line");
